assignments.referenceSolution:
The expiry predicate lives in one function and is evaluated inside the repository's lock, so a claim cannot race with another claim on the same expired hold. The stored status is deliberately left stale; `availability` derives the effective status instead. Validating show and seat existence in the repository gives clean `NotFoundError`s rather than `KeyError`s or silent bad rows.

**`booking_service.py`**

```python
import threading
from collections.abc import Callable, Iterable
from dataclasses import dataclass
from datetime import datetime, timedelta
from enum import Enum, auto


class NotFoundError(LookupError):
    pass


class SeatUnavailableError(RuntimeError):
    pass


class HoldExpiredError(SeatUnavailableError):
    pass


class Status(Enum):
    AVAILABLE = auto()
    BLOCKED = auto()
    BOOKED = auto()


@dataclass
class Seat:
    label: str
    status: Status = Status.AVAILABLE
    holder: str | None = None
    blocked_at: datetime | None = None


def _expired(seat: Seat, now: datetime, hold: timedelta) -> bool:
    return (
        seat.status is Status.BLOCKED
        and seat.blocked_at is not None
        and now - seat.blocked_at > hold
    )


class InMemorySeatRepository:
    def __init__(self) -> None:
        self._shows: dict[int, dict[str, Seat]] = {}
        self._lock = threading.Lock()

    def add_show(self, show_id: int, labels: Iterable[str]) -> None:
        with self._lock:
            seats = self._shows.setdefault(show_id, {})
            for label in labels:
                seats.setdefault(label, Seat(label))

    def _lookup(self, show_id: int, labels: Iterable[str]) -> list[Seat]:
        seats = self._shows.get(show_id)
        if seats is None:
            raise NotFoundError(f"show {show_id} does not exist")
        found: list[Seat] = []
        for label in labels:
            if label not in seats:
                raise NotFoundError(f"seat {label} does not exist in show {show_id}")
            found.append(seats[label])
        return found

    def claim(
        self, show_id: int, labels: Iterable[str], user: str, now: datetime, hold: timedelta
    ) -> None:
        with self._lock:
            seats = self._lookup(show_id, labels)
            for seat in seats:
                if not (seat.status is Status.AVAILABLE or _expired(seat, now, hold)):
                    raise SeatUnavailableError(f"seat {seat.label} is not available")
            for seat in seats:
                seat.status = Status.BLOCKED
                seat.holder = user
                seat.blocked_at = now

    def confirm(
        self, show_id: int, labels: Iterable[str], user: str, now: datetime, hold: timedelta
    ) -> None:
        with self._lock:
            seats = self._lookup(show_id, labels)
            for seat in seats:
                if seat.status is not Status.BLOCKED or seat.holder != user:
                    raise SeatUnavailableError(f"seat {seat.label} is not held by {user}")
                if _expired(seat, now, hold):
                    raise HoldExpiredError(f"hold on seat {seat.label} has expired")
            for seat in seats:
                seat.status = Status.BOOKED

    def raw_status(self, show_id: int) -> dict[str, tuple[Status, str | None]]:
        with self._lock:
            seats = self._shows.get(show_id)
            if seats is None:
                raise NotFoundError(f"show {show_id} does not exist")
            return {label: (s.status, s.holder) for label, s in seats.items()}

    def effective_status(self, show_id: int, now: datetime, hold: timedelta) -> dict[str, str]:
        with self._lock:
            seats = self._shows.get(show_id)
            if seats is None:
                raise NotFoundError(f"show {show_id} does not exist")
            return {
                label: (Status.AVAILABLE if _expired(s, now, hold) else s.status).name
                for label, s in seats.items()
            }


class BookingService:
    def __init__(
        self,
        repo: InMemorySeatRepository,
        clock: Callable[[], datetime],
        hold: timedelta = timedelta(minutes=15),
    ) -> None:
        self.repo = repo
        self.clock = clock
        self.hold = hold

    def _now(self) -> datetime:
        now = self.clock()
        if now.utcoffset() is None:
            raise ValueError("clock must return a timezone-aware datetime")
        return now

    @staticmethod
    def _labels(labels: Iterable[str]) -> list[str]:
        unique = sorted(set(labels))
        if not unique:
            raise ValueError("labels must not be empty")
        return unique

    def hold_seats(self, show_id: int, labels: Iterable[str], user: str) -> None:
        self.repo.claim(show_id, self._labels(labels), user, self._now(), self.hold)

    def confirm(self, show_id: int, labels: Iterable[str], user: str) -> None:
        self.repo.confirm(show_id, self._labels(labels), user, self._now(), self.hold)

    def availability(self, show_id: int) -> dict[str, str]:
        return self.repo.effective_status(show_id, self._now(), self.hold)
```

**`test_booking_service.py`**

```python
import threading
from datetime import datetime, timedelta, timezone

import pytest

from booking_service import (
    BookingService,
    HoldExpiredError,
    InMemorySeatRepository,
    NotFoundError,
    SeatUnavailableError,
    Status,
)

T0 = datetime(2026, 11, 1, 14, 0, tzinfo=timezone.utc)


def make(labels=("C3", "C4", "C5")):
    now = [T0]
    repo = InMemorySeatRepository()
    repo.add_show(1, labels)
    return BookingService(repo, clock=lambda: now[0]), repo, now


def test_hold_blocks_seats_for_the_user():
    svc, repo, _ = make()
    svc.hold_seats(1, ["C3", "C4"], "alice")
    assert repo.raw_status(1)["C3"] == (Status.BLOCKED, "alice")
    assert svc.availability(1) == {"C3": "BLOCKED", "C4": "BLOCKED", "C5": "AVAILABLE"}


def test_second_user_is_refused_until_hold_expires_strictly():
    svc, repo, now = make()
    svc.hold_seats(1, ["C4"], "alice")
    now[0] = T0 + timedelta(minutes=15)           # exactly the window: still held
    with pytest.raises(SeatUnavailableError):
        svc.hold_seats(1, ["C4"], "bob")
    now[0] = T0 + timedelta(minutes=15, seconds=1)
    svc.hold_seats(1, ["C4"], "bob")
    assert repo.raw_status(1)["C4"] == (Status.BLOCKED, "bob")


def test_stored_status_stays_stale_but_availability_is_effective():
    svc, repo, now = make()
    svc.hold_seats(1, ["C4"], "alice")
    now[0] = T0 + timedelta(minutes=19)
    assert repo.raw_status(1)["C4"] == (Status.BLOCKED, "alice")
    assert svc.availability(1)["C4"] == "AVAILABLE"


def test_claim_is_all_or_nothing():
    svc, repo, _ = make()
    svc.hold_seats(1, ["C4"], "alice")
    with pytest.raises(SeatUnavailableError):
        svc.hold_seats(1, ["C3", "C4"], "bob")
    assert repo.raw_status(1)["C3"] == (Status.AVAILABLE, None)


def test_unknown_show_or_seat_is_not_found_and_changes_nothing():
    svc, repo, _ = make()
    with pytest.raises(NotFoundError):
        svc.hold_seats(2, ["C3"], "alice")
    with pytest.raises(NotFoundError):
        svc.hold_seats(1, ["C3", "Z9"], "alice")
    assert repo.raw_status(1)["C3"] == (Status.AVAILABLE, None)


def test_confirm_rules():
    svc, repo, now = make()
    svc.hold_seats(1, ["C3"], "alice")
    with pytest.raises(SeatUnavailableError):
        svc.confirm(1, ["C3"], "bob")                # not the holder
    svc.confirm(1, ["C3"], "alice")
    assert repo.raw_status(1)["C3"] == (Status.BOOKED, "alice")
    with pytest.raises(SeatUnavailableError):
        svc.confirm(1, ["C4"], "alice")              # never held

    svc.hold_seats(1, ["C5"], "alice")
    now[0] = T0 + timedelta(minutes=20)
    with pytest.raises(HoldExpiredError):
        svc.confirm(1, ["C5"], "alice")
    assert repo.raw_status(1)["C5"] == (Status.BLOCKED, "alice")


def test_input_validation():
    svc, _, _ = make()
    with pytest.raises(ValueError):
        svc.hold_seats(1, [], "alice")
    svc.hold_seats(1, ["C3", "C3"], "alice")
    naive = BookingService(InMemorySeatRepository(), clock=lambda: datetime(2026, 11, 1))
    with pytest.raises(ValueError):
        naive.availability(1)


def test_concurrent_claims_on_an_expired_hold_have_one_winner():
    svc, repo, now = make()
    svc.hold_seats(1, ["C4"], "ghost")
    now[0] = T0 + timedelta(hours=1)
    winners: list[str] = []
    guard = threading.Lock()

    def attempt(user: str) -> None:
        try:
            svc.hold_seats(1, ["C4"], user)
        except SeatUnavailableError:
            return
        with guard:
            winners.append(user)

    threads = [threading.Thread(target=attempt, args=(f"user{i}",)) for i in range(16)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert len(winners) == 1
    assert repo.raw_status(1)["C4"] == (Status.BLOCKED, winners[0])
